package com.tickethub.paymentservice.controller;
import com.tickethub.paymentservice.dto.request.*; import com.tickethub.paymentservice.dto.response.PaymentResponse; import com.tickethub.paymentservice.security.JwtAuthenticationFilter.JwtPrincipal; import com.tickethub.paymentservice.service.PaymentReconciliationService; import com.tickethub.paymentservice.service.PaymentService; import io.swagger.v3.oas.annotations.*; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.security.core.Authentication; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/payments") @Tag(name="Payments") public class PaymentController {private final PaymentService paymentService; private final PaymentReconciliationService reconciliationService; public PaymentController(PaymentService p,PaymentReconciliationService r){paymentService=p;reconciliationService=r;}
 private Long user(Authentication a){return Long.valueOf(((JwtPrincipal)a.getPrincipal()).userId());}
 @PostMapping public ResponseEntity<PaymentResponse> create(@Valid @RequestBody CreatePaymentRequest r,Authentication a){return ResponseEntity.status(201).body(paymentService.createPayment(r,user(a)));}
 @PostMapping("/verify") public PaymentResponse verify(@Valid @RequestBody VerifyPaymentRequest r,Authentication a){PaymentResponse p=paymentService.verifyPayment(r,user(a));if(!Objects.equals(user(a),p.userId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Payment not found");return p;}
 @GetMapping("/{paymentReference}") public PaymentResponse get(@PathVariable String paymentReference,Authentication a){return paymentService.getPayment(paymentReference,user(a));}
 @GetMapping("/booking/{bookingId}") public List<PaymentResponse> getByBooking(@PathVariable Long bookingId,Authentication a){return paymentService.getPaymentsByBooking(bookingId,user(a));}
 @PostMapping("/{paymentReference}/refund") public PaymentResponse refund(@PathVariable String paymentReference,Authentication a){return paymentService.refundPayment(paymentReference,user(a));}
 @PreAuthorize("hasRole('ADMIN')") @PostMapping("/reconcile") public Map<String,Integer> reconcile(){return Map.of("updated",reconciliationService.reconcilePendingPayments());}
 @GetMapping("/reconciliation/report") public Map<String, Object> reconciliationReport(){return reconciliationService.generateReconciliationAudit();}
}
